function data = improanalysis(nmat,wlen,tmin,tmax,col,input,output);%function data = improanalysis(nmat,wlen,<tmin>,<tmax>,<col>,<input>,<output>);% input parameters:%   NMAT = note matrix to be analysed%   WLEN = length of analysis window in secs%   TMIN (optional, default = 0) = start point of analysis in secs%   TMAX (optional, default = end of NMAT) = end point of analysis in secs%   COL (optional, default=0) = output color%       0 = color output for screen%       1 = b/w output for printout%warning offwstep=1;on=onsetsec(nmat); du=dursec(nmat);if nargin<7 output=0; endif nargin<6 input=0; endif nargin<5 col=0; endif nargin<4 tmax=on(end)+du(end); endif nargin<3 tmin=0; endif nargin<2    wlen=6; disp('Window length set to 6 secs.');endif ischar(nmat)    files = dir(nmat);    cd(nmat)    stat = [];    for i = 1:size(files,1);        i        name = files(i).name        stat = [stat improstatanalysis(readmidi(name),wlen,tmin,tmax)];    endendif col==0    c1='k-'; c2='g-';else    c1='k-'; c2='k--';endnm=shift(onsetwindow(nmat,tmin,tmax,'sec'),'onset',-tmin);mc=mchannels(nmat);if length(mc)==1    disp(['Data found on 1 channel only!']);elseif length(mc)>2    disp(['Data found on ' num2str(length(mc)) ' channels!']);    disp('First 2 channels displayed.');endif input    load(input)endnm1=getmidich(nm,mc(1));stdp1=movewindow2(nm1,tmin,tmax,wlen,wstep,'sec','pitch','std');meanp1=movewindow2(nm1,tmin,tmax,wlen,wstep,'sec','pitch','mean');meanv1=movewindow2(nm1,tmin,tmax,wlen,wstep,'sec','velocity','mean');ton1=movewindow2(nm1,tmin,tmax,wlen,wstep,'sec','maxkkcc');dens1=movewindow2(nm1,tmin,tmax,wlen,wstep,'sec','nnotes')/wlen;dur1=movewindow2(nm1,tmin,tmax,wlen,wstep,'sec','dursec','duraccent','mean');ac1=movewindow2(nm1,tmin,tmax,wlen,wstep,'sec','pulsesalience');art1=movewindow2(nm1,tmin,tmax,wlen,wstep,'sec','articulation');data1=[dens1 dur1 meanp1 stdp1 meanv1 ac1 ton1 art1];data=data1;if length(mc)>1	nm2=getmidich(nm,mc(2));	stdp2=movewindow2(nm2,tmin,tmax,wlen,wstep,'sec','pitch','std');	meanp2=movewindow2(nm2,tmin,tmax,wlen,wstep,'sec','pitch','mean');	meanv2=movewindow2(nm2,tmin,tmax,wlen,wstep,'sec','velocity','mean');	ton2=movewindow2(nm2,tmin,tmax,wlen,wstep,'sec','maxkkcc');	dens2=movewindow2(nm2,tmin,tmax,wlen,wstep,'sec','nnotes')/wlen;	dur2=movewindow2(nm2,tmin,tmax,wlen,wstep,'sec','dursec','duraccent','mean');	ac2=movewindow2(nm2,tmin,tmax,wlen,wstep,'sec','pulsesalience');	art2=movewindow2(nm2,tmin,tmax,wlen,wstep,'sec','articulation');		data2=[dens2 dur2 meanp2 stdp2 meanv2 ac2 ton2 art2];	data=[data1; data2];endt=tmin:wstep:tmax;clf; if col==1 fsize=6; % font sizeelse fsize=9;endif length(mc)==1subplot('Position',[0.1 0.8 0.88 0.2]),pianoroll(nm1,'hold');axis([tmin tmax get(gca,'YLim')]);  set(gca,'FontSize',fsize);else    subplot('Position',[0.1 0.9 0.88 0.095]),pianoroll(nm1,'hold');axis([tmin tmax get(gca,'YLim')]);  set(gca,'FontSize',fsize);	subplot('Position',[0.1 0.8 0.88 0.095]),pianoroll(nm2,'hold');axis([tmin tmax get(gca,'YLim')]); set(gca,'FontSize',fsize);endN=8; ypos=0.1+0.7*(1-(1:N)/N);n=0; dx=0.88; dy=0.7/N-0.005;if length(mc)>1 maxdens=max([dens1; dens2]); else maxdens=max(dens1);  endn=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,dens1,c1);if input    axis([tmin tmax 0 max(maxdens,stat.dens.mean+1*stat.dens.std)])else    axis([tmin tmax 0 maxdens])endif length(mc)>1 hold on,plot(t,dens2,c2);hold off; endylabel('density','FontSize',fsize); set(gca,'FontSize',fsize);if inputhold onplot([tmin tmax],[stat.dens.mean stat.dens.mean],'r--')plot([tmin tmax],[stat.dens.mean-1*stat.dens.std stat.dens.mean-1*stat.dens.std],'b:')plot([tmin tmax],[stat.dens.mean+1*stat.dens.std stat.dens.mean+1*stat.dens.std],'b:')endif length(mc)>1 maxdur=max([dur1; dur2]); else maxdur=max(dur1); endn=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,dur1,c1);if input    axis([tmin tmax 0 max(maxdur,stat.dur.mean+1*stat.dur.std)])else    axis([tmin tmax 0 maxdur])endif length(mc)>1 hold on, plot(t,dur2,c2);hold off; endylabel('mean dur','FontSize',fsize); set(gca,'FontSize',fsize);if inputhold onplot([tmin tmax],[stat.dur.mean stat.dur.mean],'r--')plot([tmin tmax],[stat.dur.mean-1*stat.dur.std stat.dur.mean-1*stat.dur.std],'b:')plot([tmin tmax],[stat.dur.mean+1*stat.dur.std stat.dur.mean+1*stat.dur.std],'b:')endn=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,meanp1,c1); axis([tmin tmax 0 127])if length(mc)>1 hold on, plot(t,meanp2,c2);hold off; endylabel('mean pitch','FontSize',fsize); set(gca,'FontSize',fsize);if inputhold onplot([tmin tmax],[stat.meanp.mean stat.meanp.mean],'r--')plot([tmin tmax],[stat.meanp.mean-1*stat.meanp.std stat.meanp.mean-1*stat.meanp.std],'b:')plot([tmin tmax],[stat.meanp.mean+1*stat.meanp.std stat.meanp.mean+1*stat.meanp.std],'b:')endif length(mc)>1 pran=max([stdp1;stdp2]); else pran=max(stdp1); endn=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,stdp1,c1);if input    axis([tmin tmax 0 max(pran,stat.stdp.mean+1*stat.stdp.std)])else    axis([tmin tmax 0 pran])endif length(mc)>1 hold on, plot(t,stdp2,c2); hold off; endylabel('pitch std','FontSize',fsize); set(gca,'FontSize',fsize);if inputhold onplot([tmin tmax],[stat.stdp.mean stat.stdp.mean],'r--')plot([tmin tmax],[stat.stdp.mean-1*stat.stdp.std stat.stdp.mean-1*stat.stdp.std],'b:')plot([tmin tmax],[stat.stdp.mean+1*stat.stdp.std stat.stdp.mean+1*stat.stdp.std],'b:')endn=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,meanv1,c1); axis([tmin tmax 0 127])if length(mc)>1 hold on, plot(t,meanv2,c2); hold off; endylabel('mean vel','FontSize',fsize); set(gca,'FontSize',fsize);if inputhold onplot([tmin tmax],[stat.meanv.mean stat.meanv.mean],'r--')plot([tmin tmax],[stat.meanv.mean-1*stat.meanv.std stat.meanv.mean-1*stat.meanv.std],'b:')plot([tmin tmax],[stat.meanv.mean+1*stat.meanv.std stat.meanv.mean+1*stat.meanv.std],'b:')endif length(mc)>1 acran=max([ac1;ac2]); else acran=max(ac1); endn=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,ac1,c1);if input    axis([tmin tmax 0 max(acran,stat.ac.mean+1*stat.ac.std)])else    axis([tmin tmax 0 acran])endif length(mc)>1 hold on, plot(t,ac2,c2); hold off; endylabel('pulseclar','FontSize',fsize); set(gca,'FontSize',fsize);if inputhold onplot([tmin tmax],[stat.ac.mean stat.ac.mean],'r--')plot([tmin tmax],[stat.ac.mean-1*stat.ac.std stat.ac.mean-1*stat.ac.std],'b:')plot([tmin tmax],[stat.ac.mean+1*stat.ac.std stat.ac.mean+1*stat.ac.std],'b:')endn=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,ton1,c1); axis([tmin tmax 0 1])if length(mc)>1 hold on, plot(t,ton2,c2);hold off; endylabel('tonality','FontSize',fsize); set(gca,'FontSize',fsize);if inputhold onplot([tmin tmax],[stat.ton.mean stat.ton.mean],'r--')plot([tmin tmax],[stat.ton.mean-1*stat.ton.std stat.ton.mean-1*stat.ton.std],'b:')plot([tmin tmax],[stat.ton.mean+1*stat.ton.std stat.ton.mean+1*stat.ton.std],'b:')endn=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,art1,c1); axis([tmin tmax 0 1])if length(mc)>1 hold on, plot(t,art2,c2);hold off; endylabel('articulation','FontSize',fsize); set(gca,'FontSize',fsize);if inputhold onplot([tmin tmax],[stat.art.mean stat.art.mean],'r--')plot([tmin tmax],[stat.art.mean-1*stat.art.std stat.art.mean-1*stat.art.std],'b:')plot([tmin tmax],[stat.art.mean+1*stat.art.std stat.art.mean+1*stat.art.std],'b:')endif output    dens1 = dens1(~isnan(dens1));    dur1 = dur1(~isnan(dur1));    meanp1 = meanp1(~isnan(meanp1));    stdp1 = stdp1(~isnan(stdp1));    meanv1 = meanv1(~isnan(meanv1));    ac1 = ac1(~isnan(ac1));    ton1 = ton1(~isnan(ton1));    art1 = art1(~isnan(art1));    if input        stat.dens.mean        stat.dens.mean * stat.size + mean(dens1)        stat.dens.mean = (stat.dens.mean * stat.size + mean(dens1)) / (stat.size + 1)        stat.dens.std = sqrt((stat.dens.std^2 * stat.size + var(dens1)) / (stat.size + 1));        stat.dur.mean = (stat.dur.mean * stat.size + mean(dur1)) / (stat.size + 1);        stat.dur.std = sqrt((stat.dur.std^2 * stat.size + var(dur1)) / (stat.size + 1));        stat.meanp.mean = (stat.meanp.mean * stat.size + mean(meanp1)) / (stat.size + 1);        stat.meanp.std = sqrt((stat.meanp.std^2 * stat.size + var(meanp1)) / (stat.size + 1));        stat.stdp.mean = (stat.stdp.mean * stat.size + mean(stdp1)) / (stat.size + 1);        stat.stdp.std = sqrt((stat.stdp.std^2 * stat.size + var(stdp1)) / (stat.size + 1));        stat.meanv.mean = (stat.meanv.mean * stat.size + mean(meanv1)) / (stat.size + 1);        stat.meanv.std = sqrt((stat.meanv.std^2 * stat.size + var(meanv1)) / (stat.size + 1));        stat.ac.mean = (stat.ac.mean * stat.size + mean(ac1)) / (stat.size + 1);        stat.ac.std = sqrt((stat.ac.std^2 * stat.size + var(ac1)) / (stat.size + 1));        stat.ton.mean = (stat.ton.mean * stat.size + mean(ton1)) / (stat.size + 1);        stat.ton.std = sqrt((stat.ton.std^2 * stat.size + var(ton1)) / (stat.size + 1));        stat.art.mean = (stat.art.mean * stat.size + mean(art1)) / (stat.size + 1);        stat.art.std = sqrt((stat.art.std^2 * stat.size + var(art1)) / (stat.size + 1));        stat.size = stat.size + 1;    else        stat.dens.mean = mean(dens1);        stat.dens.std = std(dens1);        stat.dur.mean = mean(dur1);        stat.dur.std = std(dur1);        stat.meanp.mean = mean(meanp1);        stat.meanp.std = std(meanp1);        stat.stdp.mean = mean(stdp1);        stat.stdp.std = std(stdp1);        stat.meanv.mean = mean(meanv1);        stat.meanv.std = std(meanv1);        stat.ac.mean = mean(ac1);        stat.ac.std = std(ac1);        stat.ton.mean = mean(ton1);        stat.ton.std = std(ton1);        stat.art.mean = mean(art1);        stat.art.std = std(art1);        stat.size = 1;    end    save(output,'stat');end